import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·10","description":"易小帖 - 卷三·10","frontmatter":{"title":"卷三·10","description":"易小帖 - 卷三·10"},"headers":[],"relativePath":"classics/yixiaotie/078.md","filePath":"classics/yixiaotie/078.md"}'),o={name:"classics/yixiaotie/078.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·10",tabindex:"-1"},[r("卷三·10 "),e("a",{class:"header-anchor",href:"#卷三·10","aria-label":"Permalink to “卷三·10”"},"​")],-1),e("p",null,"革「已日乃孚」漢儒皆作已革之日解。然彖詞已革之日乃始孚信，猶雲民不可與慮始，必既革而後信之，尚可通也。至爻詞六二已日乃革之，則不通矣。豈有已革之後，乃始革之。為成文者，惟朱漢上震以先後庚甲推之，當是戊己之己，此是確解。但戊己之己亦有數義，一說金曰從革，於乾為庚，兌之行也，遇離而革，先金一日為己，居火金之間，正革之當其時者。一說十乾至庚有更革之義，自庚至己，十日浹矣。己日，浹日也。革不即孚，浹日乃孚。所謂乃者，有待之詞耳。一說天有十日，甲至戊為前五日，己至癸為後五日。變革，天下之事，不當輕遽，如以十日為率，與其革於未及中半之前，不若革於已過中半之後，亦所謂不輕革者，乃者難詞也。一說戊己屬土，己則陰土也。陰土者濕土，為金之母。凡四時之行，火金為序，金生於火，必伏之未土之中。今離火將尅兌金，則中隔未土以為轉尅為生之地，故月令於金火之間置一中央土，卦位於離兌之間，置一西南坤，則此卦上兌下離，接以己土，於義甚合。舊舉諸說，仲氏極以後說為當。既而又謂：己土之說，亦即己日中該之，但火金之尅藉土為生，是調和之，非革之也，遂不從。蓋說有極精而仍未當者，如此甚夥，不可不辨。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
